data.query:
query Query($where: ProductWhereInput, $orderBy: [ProductOrderByInput!], $first: Int, $after: String) {
  product(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        code
        externalId
        name
        number
        revision
        customData
        imageId
        productStageId
        productTypeId
        strategies {
      edges {
    node {
    id
  }
  }
    }
      }
    }
  }
}

